def md(frame):
 def text(v):return f'{v:.6g}' if isinstance(v,(float,np.floating)) else str(v)
 return '| '+' | '.join(map(str,frame.columns))+' |\n| '+' | '.join(['---']*len(frame.columns))+' |\n'+'\n'.join('| '+' | '.join(text(v) for v in row)+' |' for row in frame.to_numpy())
